use knownext_storage::LocalApi;
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,io::{Read,Write}};
#[test]
fn incomplete_or_future_record_preserves_every_source_and_extracts_only_reviewed_known_bytes(){
 let owned=tempfile::tempdir().unwrap();let state=owned.path().join("state");let api=LocalApi::new(state.clone(),"qa".into(),"test".into());let project=api.handle("POST","/api/projects",json!({"name":"Owned incomplete copies","versioningMode":"none","syncMode":"none"}),vec![]).unwrap().body;let project=project["id"].as_str().unwrap();let id="mixed-88888888888888888888888888888888";let folder=state.join("mixed-applications").join(format!("{:x}",Sha256::digest(project.as_bytes()))).join(id);fs::create_dir_all(&folder).unwrap();let plain=b"# Owned recoverable text\n";let binary=b"owned binary\0data";fs::write(folder.join("000-before.bin"),plain).unwrap();let mut zip=zip::ZipWriter::new(std::io::Cursor::new(Vec::new()));zip.start_file("payload.bin",zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated)).unwrap();zip.write_all(binary).unwrap();let packed=zip.finish().unwrap().into_inner();fs::write(folder.join("000-after.bin.zip"),&packed).unwrap();fs::write(folder.join("001-before.bin.zip"),b"future-container").unwrap();fs::write(folder.join("unknown.keep"),b"preserve-extra").unwrap();let endpoint=format!("/api/projects/{project}/sync/mixed-selections/{id}/application/copies");let review=api.handle("GET",&endpoint,Value::Null,vec![]).unwrap().body;assert_eq!(review["recordState"],"missing");assert_eq!(review["rows"].as_array().unwrap().len(),3);assert_eq!(review["rows"].as_array().unwrap().iter().filter(|r|r["status"]=="readable").count(),2);assert_eq!(review["limited"],true);assert_eq!(review["canApply"],false);assert_eq!(review["canDelete"],false);let revision=review["revision"].as_str().unwrap();assert!(api.freeze_incomplete_mixed(project,id,revision,"000-before.bin",false).is_err());assert!(api.freeze_incomplete_mixed(project,id,revision,"../unknown.keep",true).is_err());assert!(api.freeze_incomplete_mixed(project,id,revision,"001-before.bin.zip",true).is_err());let frozen=api.freeze_incomplete_mixed(project,id,revision,"000-before.bin",true).unwrap();let destination=owned.path().join("content.zip");api.write_system_recovery(&frozen,&destination).unwrap();let mut archive=zip::ZipArchive::new(fs::File::open(&destination).unwrap()).unwrap();assert_eq!(archive.len(),2);let mut content=vec![];archive.by_name("Contenido.bin").unwrap().read_to_end(&mut content).unwrap();assert_eq!(content,plain);let manifest:Value=serde_json::from_reader(archive.by_name("knownext-extracted.json").unwrap()).unwrap();assert_eq!(manifest["provenanceVerified"],false);assert_eq!(manifest["authorityIncluded"],false);assert!(manifest.get("projectId").is_none());
 fs::write(folder.join("record.json"),b"{\"format\":99,\"doNotAdopt\":true}").unwrap();assert!(api.freeze_incomplete_mixed(project,id,revision,"000-before.bin",true).is_err());let future=fs::read(folder.join("record.json")).unwrap();let review=api.handle("GET",&endpoint,Value::Null,vec![]).unwrap().body;assert_eq!(review["recordState"],"present");let frozen=api.freeze_incomplete_mixed(project,id,review["revision"].as_str().unwrap(),"000-after.bin.zip",true).unwrap();let second=owned.path().join("binary.zip");api.write_system_recovery(&frozen,&second).unwrap();let mut archive=zip::ZipArchive::new(fs::File::open(&second).unwrap()).unwrap();let mut recovered=vec![];archive.by_name("Contenido.bin").unwrap().read_to_end(&mut recovered).unwrap();assert_eq!(recovered,binary);assert_eq!(fs::read(folder.join("record.json")).unwrap(),future);assert_eq!(fs::read(folder.join("000-before.bin")).unwrap(),plain);assert_eq!(fs::read(folder.join("000-after.bin.zip")).unwrap(),packed);assert_eq!(fs::read(folder.join("001-before.bin.zip")).unwrap(),b"future-container");assert_eq!(fs::read(folder.join("unknown.keep")).unwrap(),b"preserve-extra");let original_revision=review["revision"].as_str().unwrap();fs::write(folder.join("000-before.bin"),b"newer preserved bytes").unwrap();assert!(api.freeze_incomplete_mixed(project,id,original_revision,"000-after.bin.zip",true).is_err());assert_eq!(fs::read(folder.join("000-before.bin")).unwrap(),b"newer preserved bytes");
}
